(()=>{
const definitions=[{id:'drink',folder:'drink',title:'Su içmek',text:'Çocuk bardağı ağzına götürüyor, su içiyor ve indiriyor.',focus:'Bardağa ve ağza bak.'},{id:'throw',folder:'ball',title:'Top atmak',text:'Soldaki çocuk topu karşısındaki çocuğa atıyor.',focus:'Soldaki çocuğa bak.'},{id:'catch',folder:'ball',title:'Top tutmak',text:'Sağdaki çocuk gelen topu iki eliyle tutuyor.',focus:'Sağdaki çocuğa bak.'},{id:'sit',folder:'sit',title:'Oturmak',text:'Çocuk dizlerini büküyor ve sandalyeye oturuyor.',focus:'Çocuğun nasıl oturduğuna bak.'}];
const runs=[],grid=document.getElementById('motionGrid'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
function timeline(ms){if(ms<250)return{a:0,b:0,blend:0,phase:'Başlangıç'};if(ms<4750){const p=(ms-250)/900,at=Math.floor(p),raw=Math.max(0,Math.min(1,p-at)),blend=raw*raw*(3-2*raw);return{a:Math.min(5,at),b:Math.min(5,at+1),blend,phase:'Hareket'};}if(ms<5450)return{a:5,b:5,blend:0,phase:'Sonuç'};const raw=Math.max(0,Math.min(1,(ms-5450)/550)),blend=raw*raw*(3-2*raw);return{a:5,b:0,blend,phase:'Yumuşak döngü'};}
window.ActionPhotoTimeline=timeline;
async function loadFrames(folder){return Promise.all(Array.from({length:6},(_,i)=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Görsel yüklenemedi'));img.src=`./assets/actions/${folder}/${i+1}.webp`;})));}
const shared=new Map();function draw(r){if(!r.frames)return;const f=timeline(r.elapsed),ctx=r.context;ctx.clearRect(0,0,768,768);ctx.globalAlpha=1;ctx.drawImage(r.frames[f.a],0,0,768,768);if(f.a!==f.b){ctx.globalAlpha=f.blend;ctx.drawImage(r.frames[f.b],0,0,768,768);ctx.globalAlpha=1;}if(r.phase.textContent!==f.phase)r.phase.textContent=f.phase;}
for(const d of definitions){const card=document.createElement('article');card.className='motion-card';card.innerHTML=`<div class="motion-photo"><canvas class="motion-scene" width="768" height="768" role="img" aria-label="${d.text}"></canvas><span class="photo-focus">${d.focus}</span></div><div class="motion-copy"><h2>${d.title}</h2><p>${d.text}</p><div class="motion-controls"><span class="motion-phase">Görseller yükleniyor…</span><button class="secondary-button compact motion-pause" disabled>${reduce?'Diziyi başlat':'Duraklat'}</button><button class="text-button motion-replay" disabled>Baştan izle</button></div></div>`;grid.append(card);const r={def:d,context:card.querySelector('canvas').getContext('2d'),phase:card.querySelector('.motion-phase'),button:card.querySelector('.motion-pause'),replay:card.querySelector('.motion-replay'),elapsed:0,last:0,playing:!reduce,visible:false,frames:null};runs.push(r);if(!shared.has(d.folder))shared.set(d.folder,loadFrames(d.folder));shared.get(d.folder).then(frames=>{r.frames=frames;r.button.disabled=r.replay.disabled=false;draw(r);}).catch(()=>{r.phase.textContent='Görseller yüklenemedi. Sayfayı yenileyin.';});r.button.onclick=()=>{r.playing=!r.playing;r.last=0;r.button.textContent=r.playing?'Duraklat':'Devam et';};r.replay.onclick=()=>{r.elapsed=0;r.last=0;r.playing=true;r.button.textContent='Duraklat';draw(r);};new IntersectionObserver(entries=>{r.visible=entries[0].isIntersecting;r.last=0;if(r.visible)draw(r);}).observe(card);}
let raf;function animate(now){for(const r of runs){if(!document.hidden&&r.playing&&r.visible&&r.frames){if(r.last)r.elapsed=(r.elapsed+Math.min(50,now-r.last))%6000;r.last=now;draw(r);}else r.last=0;}raf=requestAnimationFrame(animate);}raf=requestAnimationFrame(animate);document.addEventListener('visibilitychange',()=>runs.forEach(r=>r.last=0));window.addEventListener('pagehide',()=>cancelAnimationFrame(raf));document.getElementById('motionBack').onclick=()=>{if(parent!==window)parent.postMessage({type:'action-preview-menu'},location.origin);else location.href='./';};
})();

